PRAGMA foreign_keys=ON;
CREATE TABLE participants(id TEXT PRIMARY KEY,regAudioKey TEXT,spokenInstitution TEXT,nationalId TEXT UNIQUE,name TEXT,passwordHash TEXT,recoveryPhone TEXT,institution TEXT,track TEXT DEFAULT 'easy',nextTrack TEXT,trackEffective TEXT,balance INTEGER DEFAULT 0 CONSTRAINT nonnegative_balance CHECK(balance>=0),debt INTEGER NOT NULL DEFAULT 0,blocked INTEGER DEFAULT 0,createdAt TEXT);
CREATE TABLE exams(id TEXT PRIMARY KEY,title TEXT,materialKey TEXT,week TEXT,track TEXT,kind TEXT,opensAt TEXT,closesAt TEXT,questionCount INTEGER,bonusCount INTEGER NOT NULL DEFAULT 0,category TEXT,parsha TEXT,questions TEXT,published INTEGER DEFAULT 0,createdAt TEXT);
CREATE TABLE attempts(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),examId TEXT REFERENCES exams(id),materialKey TEXT,snapshot TEXT,completed INTEGER DEFAULT 0,score INTEGER DEFAULT 0,createdAt TEXT,completedAt TEXT,UNIQUE(participantId,materialKey));
CREATE TABLE answers(id TEXT PRIMARY KEY,attemptId TEXT REFERENCES attempts(id),questionId TEXT,choice INTEGER,points INTEGER,createdAt TEXT,UNIQUE(attemptId,questionId));
CREATE TABLE ledger(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),delta INTEGER,reason TEXT,reference TEXT UNIQUE,actor TEXT,createdAt TEXT);
CREATE TRIGGER ledger_apply AFTER INSERT ON ledger BEGIN UPDATE participants SET balance=balance+NEW.delta-MIN(debt,MAX(NEW.delta,0)),debt=debt-MIN(debt,MAX(NEW.delta,0)) WHERE id=NEW.participantId; END;
CREATE TRIGGER ledger_no_update BEFORE UPDATE ON ledger BEGIN SELECT RAISE(ABORT,'ledger_immutable'); END;
CREATE TRIGGER ledger_no_delete BEFORE DELETE ON ledger BEGIN SELECT RAISE(ABORT,'ledger_immutable'); END;
CREATE TABLE benefits(id TEXT PRIMARY KEY,title TEXT,merchant TEXT,branch TEXT,kind TEXT,cost INTEGER CHECK(cost>0),faceValue INTEGER DEFAULT 0,opensAt TEXT,closesAt TEXT,redeemUntil TEXT,delivery TEXT DEFAULT 'export',active INTEGER DEFAULT 1,createdAt TEXT);
CREATE TABLE cards(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),network TEXT,number TEXT,approved INTEGER DEFAULT 1,createdAt TEXT,UNIQUE(participantId,network));
CREATE TABLE orders(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),benefitId TEXT REFERENCES benefits(id),quantity INTEGER CHECK(quantity>0),total INTEGER,cardNumber TEXT,status TEXT,code TEXT UNIQUE,requestKey TEXT UNIQUE,snapshot TEXT,createdAt TEXT,exportedAt TEXT,completedAt TEXT);
CREATE TABLE audit(id TEXT PRIMARY KEY,actor TEXT,action TEXT,target TEXT,details TEXT,createdAt TEXT);
CREATE TABLE sessions(tokenHash TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),expiresAt TEXT);
CREATE TABLE auth_limits(key TEXT PRIMARY KEY,failures INTEGER DEFAULT 0,until TEXT);
CREATE TABLE messages(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),subject TEXT,body TEXT,audioKey TEXT,reply TEXT,replyAudioKey TEXT,status TEXT DEFAULT 'open',createdAt TEXT);
CREATE TABLE staff(userId TEXT PRIMARY KEY,name TEXT,role TEXT,scope TEXT,createdAt TEXT);
CREATE TABLE legacy(id TEXT PRIMARY KEY,source TEXT,rowKey TEXT UNIQUE,nationalId TEXT,kind TEXT,payload TEXT,createdAt TEXT);
CREATE TABLE shipments(id TEXT PRIMARY KEY,participantId TEXT REFERENCES participants(id),kind TEXT,address TEXT,status TEXT DEFAULT 'pending',notes TEXT,createdAt TEXT);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT);CREATE TABLE IF NOT EXISTS staff_accounts(id TEXT PRIMARY KEY,username TEXT UNIQUE NOT NULL,name TEXT,passwordHash TEXT NOT NULL,role TEXT NOT NULL,scope TEXT,active INTEGER NOT NULL DEFAULT 1,createdAt TEXT);
CREATE TABLE IF NOT EXISTS staff_sessions(tokenHash TEXT PRIMARY KEY,staffId TEXT REFERENCES staff_accounts(id),expiresAt TEXT);
CREATE TABLE IF NOT EXISTS institutions(id TEXT PRIMARY KEY,name TEXT UNIQUE NOT NULL,aliases TEXT NOT NULL DEFAULT '[]',createdAt TEXT);
